import { Cli, Openapi } from "incur";

export const SUBGROUP_KEY = "x-whop-docs-subgroup";

const HTTP_METHODS = new Set([
	"get",
	"put",
	"post",
	"delete",
	"options",
	"head",
	"patch",
	"trace",
]);

type Spec = Record<string, unknown>;
type PathItem = Record<string, unknown>;

/**
 * A docs subgroup ("Preferences/Notifications") becomes nested command groups
 * (`preferences notifications`) under its tag's group.
 */
export function subgroupCommandPath(subgroup: string): string[] {
	return subgroup
		.split("/")
		.map((segment) => segment.trim())
		.filter(Boolean)
		.map((segment) => segment.toLowerCase().replace(/\s+/g, "-"));
}

function subgroupOf(operation: unknown): string | null {
	const value = (operation as Record<string, unknown> | null)?.[SUBGROUP_KEY];
	return typeof value === "string" && value.trim() ? value : null;
}

function operations(spec: Spec): [string, string, unknown][] {
	const found: [string, string, unknown][] = [];
	for (const [path, item] of Object.entries(
		(spec.paths ?? {}) as Record<string, PathItem>,
	)) {
		for (const [method, operation] of Object.entries(item)) {
			if (HTTP_METHODS.has(method)) found.push([path, method, operation]);
		}
	}
	return found;
}

export function subgroupsIn(spec: Spec): string[] {
	const subgroups = new Set<string>();
	for (const [, , operation] of operations(spec)) {
		const subgroup = subgroupOf(operation);
		if (subgroup) subgroups.add(subgroup);
	}
	return [...subgroups].sort();
}

function filterSpecBySubgroup(spec: Spec, subgroup: string | null): Spec {
	const paths: Record<string, PathItem> = {};
	for (const [path, item] of Object.entries(
		(spec.paths ?? {}) as Record<string, PathItem>,
	)) {
		const kept: PathItem = {};
		for (const [method, operation] of Object.entries(item)) {
			if (HTTP_METHODS.has(method) && subgroupOf(operation) !== subgroup) {
				continue;
			}
			kept[method] = operation;
		}
		if (Object.keys(kept).some((method) => HTTP_METHODS.has(method))) {
			paths[path] = kept;
		}
	}
	return { ...spec, paths };
}

/**
 * Builds a tag's command group with each docs subgroup as a nested group, so
 * the "Preferences/Notifications" subgroup of Users runs as
 * `users preferences notifications topics`.
 */
export async function buildSubgroupedGroup(
	name: string,
	description: string,
	spec: Spec,
	fetch: (request: Request) => Promise<Response>,
) {
	const root = Cli.create(name, { description });
	const groups = new Map<string, ReturnType<typeof Cli.create>>([["", root]]);
	const groupFor = (path: string[], labels: string[]) => {
		const key = path.join(" ");
		const existing = groups.get(key);
		if (existing) return existing;
		const parent = groupFor(path.slice(0, -1), labels.slice(0, -1));
		const group = Cli.create(path.at(-1)!, { description: labels.at(-1)! });
		parent.command(group);
		groups.set(key, group);
		return group;
	};

	for (const subgroup of [null, ...subgroupsIn(spec)]) {
		const target = subgroup
			? groupFor(
					subgroupCommandPath(subgroup),
					subgroup.split("/").map((label) => label.trim()),
				)
			: root;
		const generated = await Openapi.generateCommands(
			filterSpecBySubgroup(spec, subgroup) as Openapi.OpenAPISpec,
			fetch,
			{ config: { security: false } },
		);
		for (const [command, entry] of generated) {
			if ("run" in entry) target.command(command, entry);
		}
	}
	return root;
}
