import { join } from "node:path";
import { buildFeedbackCommand } from "./feedback";
import { Cli } from "incur";
import { nativeSpec, filterSpecByTag, createWhopFetch } from "./api";
import { buildFilesGroup } from "./files/commands.js";
import { API_GROUPS } from "./api/groups";
import { buildSubgroupedGroup, subgroupsIn } from "./api/subgroups";
import { buildAppGroup } from "./apps/commands";
import {
	buildAuthGroup,
	logoutAdapter,
	logoutOptions,
	logoutOutput,
} from "./auth/commands";
import {
	loginAdapter,
	loginEnv,
	loginExamples,
	loginHint,
	loginOptions,
	loginOutput,
} from "./auth/login";
import { buildMediaGroup } from "./media/commands";
import pkg from "../package.json" with { type: "json" };
import {
	quickstartOptions,
	quickstartOutput,
	runQuickstart,
} from "./journey/quickstart";
import { render } from "./lib/renderer";
import { materializeShippedSkills } from "./lib/shipped-skills";
import {
	runUpgrade,
	upgradeOptions,
	upgradeOutput,
} from "./lib/update/command";
import { performLogin } from "./auth/login";
import { getActiveProfile } from "./auth/profiles";
import { PromptCancelledError } from "./auth/prompts";

// Bundled into the build and written to a real temp dir at runtime so
// standalone binaries and npx (no skills/ on disk) still install it.
// Include is an absolute glob so we never set sync.cwd — incur uses cwd as
// the --no-global install destination, and pointing it at the temp dir would
// install there instead of the project.
const shippedSkillsDir = process.argv.includes("skills")
	? materializeShippedSkills()
	: undefined;

const cli = Cli.create("whop", {
	version: pkg.version,
	description: "Build and manage Whop apps from your terminal.",
	renderer: render,
	sync: {
		// One unified skill (skills-extras/whop/). depth 0 so incur does not
		// also emit a skill per command group — the included `whop` skill
		// overrides the generated root skill by frontmatter name.
		depth: 0,
		include: shippedSkillsDir ? [join(shippedSkillsDir, "*")] : ["skills/*"],
		suggestions: [
			"choose or create my Whop business account",
			"deploy a website to whop.site",
			"create a Whop product and checkout link",
			"run ads on Meta",
			"form an LLC",
		],
	},
	mcp: {
		agents: [],
		icons: [
			{
				src: "https://whop.com/apple-icon.png",
				mimeType: "image/png",
				sizes: ["512x512"],
			},
		],
	},
});

const spec = (tag: string) =>
	filterSpecByTag(nativeSpec as Record<string, unknown>, tag);
const fetch = createWhopFetch();

const isAuthExempt = (cmd: string) =>
	!cmd ||
	cmd === "login" ||
	cmd === "logout" ||
	cmd === "completions" ||
	cmd === "upgrade" ||
	cmd.startsWith("auth") ||
	cmd.startsWith("mcp");

cli.use(async (c, next) => {
	if (isAuthExempt(c.command)) return next();
	if (getActiveProfile()) return next();
	if (process.env.WHOP_API_KEY) return next();

	if (c.agent || c.formatExplicit) {
		return c.error({
			code: "NOT_AUTHENTICATED",
			message: "Not logged in. Set WHOP_API_KEY or run `whop login` first.",
			cta: {
				commands: [{ command: "auth login", description: "Log in to Whop" }],
			},
		});
	}

	let result;
	try {
		result = await performLogin({
			agent: false,
			deferAccountSelection: c.command === "quickstart",
		});
	} catch (err) {
		if (err instanceof PromptCancelledError) {
			return c.error({
				code: "CANCELLED",
				message: "Login cancelled.",
				exitCode: 130,
			});
		}
		throw err;
	}

	if (!result.ok) {
		return c.error({
			code: result.code,
			message: result.message,
			cta: {
				commands: [{ command: "auth login", description: "Log in to Whop" }],
			},
		});
	}

	return next();
});

cli.command("quickstart", {
	description: "Set up the business account the CLI should use",
	hint: "OAuth users can choose or create a business. API keys are tied to one business. Agents and scripts should pass --account_id or --business_name when the choice is ambiguous.",
	options: quickstartOptions,
	output: quickstartOutput,
	examples: [
		{ description: "Choose or create a business interactively" },
		{
			options: { account_id: "biz_xxx" },
			description: "Choose an existing business account",
		},
		{
			options: { business_name: "Acme" },
			description: "Create and select a new business account",
		},
	],
	outputPolicy: "agent-only",
	run: (c) => runQuickstart(c),
});

cli.command("report-feedback", buildFeedbackCommand("report_feedback"));
cli.command("ask-question", buildFeedbackCommand("ask_question"));

cli.command(await buildAppGroup());

cli.command("upgrade", {
	description: "Update the whop CLI to the latest version",
	options: upgradeOptions,
	output: upgradeOutput,
	examples: [
		{ description: "Update to the latest version" },
		{
			options: { check: true },
			description: "Check for a newer version without installing",
		},
	],
	run: (c) => runUpgrade(c),
});

cli.command(buildAuthGroup());

cli.command("login", {
	description: "Log in to Whop (alias for `auth login`)",
	options: loginOptions,
	env: loginEnv,
	output: loginOutput,
	examples: loginExamples,
	hint: loginHint,
	run: (c) => loginAdapter(c),
});

cli.command("logout", {
	description: "Log out (alias for `auth logout`)",
	options: logoutOptions,
	output: logoutOutput,
	run: (c) => logoutAdapter(c),
});

for (const { name, tag, description } of API_GROUPS) {
	// Media is hybrid: spec commands plus a hand-written `generate --wait`.
	if (name === "media") {
		cli.command(await buildMediaGroup(description));
		continue;
	}
	// Files is hybrid too: `create --filepath` uploads a local file end to end.
	if (name === "files") {
		cli.command(await buildFilesGroup(description));
		continue;
	}
	const tagSpec = spec(tag);
	if (subgroupsIn(tagSpec).length > 0) {
		cli.command(await buildSubgroupedGroup(name, description, tagSpec, fetch));
		continue;
	}
	cli.command(name, {
		description,
		fetch,
		openapi: tagSpec,
		openapiConfig: { security: false },
	});
}

export default cli;
