import { Cli, Openapi, z } from "incur";
import { createWhopFetch, filterSpecByTag, nativeSpec } from "../api/index.js";
import { uploadLocalFile } from "./upload.js";

type GeneratedCommand = {
	description?: string | undefined;
	options?: z.ZodObject<any> | undefined;
	run: (context: any) => any;
};

export async function buildFilesGroup(description: string) {
	const files = Cli.create("files", { description });
	const spec = filterSpecByTag(nativeSpec as Record<string, unknown>, "Files");
	const generated = await Openapi.generateCommands(
		spec as Openapi.OpenAPISpec,
		createWhopFetch(),
		{
			config: { security: false },
		},
	);
	for (const [name, entry] of generated) {
		if (!("run" in entry)) continue;
		files.command(name, name === "create" ? withLocalUpload(entry) : entry);
	}
	return files;
}

export function withLocalUpload(entry: GeneratedCommand) {
	const options = (entry.options ?? z.object({}))
		.partial({ filename: true })
		.extend({
			filepath: z
				.string()
				.optional()
				.describe(
					"Path to a local file to upload. Creates the file, uploads its bytes, and returns it once ready. --filename defaults to the file's name.",
				),
		});
	return {
		...entry,
		description:
			"Upload a local file with --filepath, or create a file record and upload its bytes yourself",
		options,
		examples: [
			{
				options: { filepath: "./ad.mp4", visibility: "public" },
				description: "Upload a local file and wait until it is ready",
			},
		],
		run: (context: { options: Record<string, any> }) => {
			const { filepath, ...rest } = context.options;
			if (filepath)
				return uploadLocalFile({
					filepath,
					filename: rest.filename,
					visibility: rest.visibility,
				});
			if (!rest.filename)
				throw new Error(
					"Pass --filepath to upload a local file, or --filename to create a file record.",
				);
			return entry.run({ ...context, options: rest });
		},
	};
}
