import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";

export const APP_CONFIG_FILENAME = "whop.app.json";

export const PLATFORM_DOMAIN_SUFFIX = "whop.site";

export type AppConfig = {
	app_id: string;
	name: string;
};

type AppIdentity = { id: string; name: string };

export function linkConfigFor(app: AppIdentity): AppConfig {
	return { app_id: app.id, name: app.name };
}

export function findProjectDir(startDir?: string): string | null {
	let dir = resolve(startDir ?? process.cwd());
	for (let i = 0; i < 25; i++) {
		if (existsSync(join(dir, APP_CONFIG_FILENAME))) return dir;
		const parent = resolve(dir, "..");
		if (parent === dir) break;
		dir = parent;
	}
	return null;
}

export function readAppConfig(projectDir: string): AppConfig | null {
	const path = join(projectDir, APP_CONFIG_FILENAME);
	if (!existsSync(path)) return null;
	try {
		const parsed = JSON.parse(
			readFileSync(path, "utf-8"),
		) as Partial<AppConfig>;
		if (typeof parsed.app_id !== "string") return null;
		return {
			app_id: parsed.app_id,
			name: typeof parsed.name === "string" ? parsed.name : parsed.app_id,
		};
	} catch {
		return null;
	}
}

export function writeAppConfig(projectDir: string, config: AppConfig): void {
	writeFileSync(
		join(projectDir, APP_CONFIG_FILENAME),
		`${JSON.stringify(config, null, "\t")}\n`,
	);
}

/** A filesystem- and worker-safe name for the app, from its name. */
export function appSlug(app: AppIdentity): string {
	return slugify(app.name) || app.id.toLowerCase().replace("_", "-");
}

/** The whop.site address for a name: `My Site 2.0` → `my-site-2-0.whop.site`. */
export function platformDomainFor(name: string): string {
	return `${slugify(name)}.${PLATFORM_DOMAIN_SUFFIX}`;
}

/** A domain someone typed: a full hostname such as `example.com` stays as it is; a bare name becomes its whop.site address. */
export function domainFor(input: string): string {
	const host = input.trim().toLowerCase();
	return host.includes(".") ? host : platformDomainFor(host);
}

export function slugify(name: string): string {
	return name
		.toLowerCase()
		.normalize("NFKD")
		.replace(/[^a-z0-9]+/g, "-")
		.replace(/^-+|-+$/g, "")
		.slice(0, 63);
}
