export const initOptions = z.object({
	app: z
		.string()
		.optional()
		.describe(
			"Start the code for this existing app (app_xxx) instead of registering a new one — for an app that has never been deployed, such as a website created on whop.com. Its name, address and type come from the app",
		),
	name: z
		.string()
		.optional()
		.describe("Name for the new app (prompted for interactively if omitted)"),
	domain: z
		.string()
		.optional()
		.describe(
			"Domain the app is served at: a whop.site name such as my-site (my-site.whop.site), or a domain the account owns. Defaults to the name's whop.site address",
		),
	template: z
		.string()
		.optional()
		.describe(
			"Clone this app's published source archive (app_xxx) instead of the blank TanStack Start template",
		),
	dir: z
		.string()
		.optional()
		.describe("Target directory (defaults to ./<app name>)"),
	app_type: z
		.enum(["b2c_app", "website"])
		.optional()
		.describe(
			"What you are building: b2c_app (creators install it into their whop) or website (visitors browse it at its domain). Asked interactively if omitted, and required when there is nobody to ask",
		),
	company_id: z
		.string()
		.optional()
		.describe(
			"Company the app belongs to (biz_xxx). Defaults to the active account, and is required when the credential has none",
		),
	imported_from_url: z
		.string()
		.optional()
		.describe(
			"URL of the existing website this app is imported from, such as https://shop.example.com",
		),
});

export const initOutput = z.object({
	app_id: z.string(),
	name: z.string(),
	domain: z.string().optional(),
	dir: z.string(),
	manual_steps: z.array(z.string()).optional(),
	domain_steps: z
		.array(z.string())
		.optional()
		.describe(
			"What the owner must do before the domain serves the app: pay at a purchase link, or publish DNS records",
		),
});

type InitOptions = z.infer<typeof initOptions>;

export type InitResult = {
	projectDir: string;
	app: WhopApp;
	manualSteps: string[];
};

/** The app a project is started for: its slug names the directory, before the app is claimed. */
type ProjectApp = { slug: string; claim: () => Promise<WhopApp> };

/**
 * Asks what is being built, or stops. There is no safe guess: a website can
 * never be turned back into an app, and an app saved as the wrong kind never
 * shows up where its owner looks for it.
 */
async function resolveAppType(
	c: CommandContext,
	name: string,
	domain: string,
): Promise<NewAppType> {
	if (!c.agent) return promptForAppType();

	throw new CommandAbort({
		code: "APP_TYPE_REQUIRED",
		message: [
			"Nothing was created. Ask the user what they are building, then re-run with --app_type:",
			"",
			`  whop apps init --name "${name}" --domain ${domain} --app_type b2c_app   (creators install it into their whop)`,
			`  whop apps init --name "${name}" --domain ${domain} --app_type website   (visitors browse it at ${domain})`,
			"",
			"Ask rather than guess: a website cannot be turned back into an app later.",
		].join("\n"),
		retryable: true,
		cta: {
			commands: [
				{
					command: "apps init",
					description: "Re-run with --app_type b2c_app or --app_type website",
				},
			],
		},
	});
}

async function resolveNameAndDomain(
	c: CommandContext,
	options: Pick<InitOptions, "name" | "domain" | "app_type">,
	templateAppType?: NewAppType,
): Promise<{ name: string; domain: string; appType: NewAppType }> {
	// The flag beats the template it was cloned from: it is the person saying
	// what they want, not a guess from what they copied.
	const knownAppType = options.app_type ?? templateAppType;

	if (options.name) {
		const domain = options.domain
			? domainFor(options.domain)
			: platformDomainFor(options.name);
		if (domain === `.${PLATFORM_DOMAIN_SUFFIX}`) {
			throw new CommandAbort({
				code: "DOMAIN_REQUIRED",
				message: `Couldn't derive a domain from "${options.domain ?? options.name}" — use letters and numbers (e.g. my-site).`,
				retryable: true,
			});
		}
		const appType =
			knownAppType ?? (await resolveAppType(c, options.name, domain));
		return { name: options.name, domain, appType };
	}

	if (c.agent) {
		throw new CommandAbort({
			code: "NAME_REQUIRED",
			message: [
				"Ask the user three things, then re-run with flags:",
				"  1. What the app is called.",
				"  2. Which domain it should live at: a whop.site name (my-site → my-site.whop.site) or a domain they own.",
				"  3. Whether they are building an app creators install into their whop, or a website visitors browse.",
				"",
				'  whop apps init --name "My Site" --domain my-site --app_type website',
				"",
				"--app_type takes b2c_app or website, and is required here. Ask rather than guess: a website cannot be turned back into an app later.",
			].join("\n"),
			retryable: true,
			cta: {
				commands: [
					{
						command: "apps init",
						description:
							"Re-run with --name and --app_type (and optionally --domain)",
					},
				],
			},
		});
	}

	if (options.domain) {
		const appType = knownAppType ?? (await promptForAppType());
		const name = await promptText("What is your app called?", "My Site");
		if (name === null) cancelled();
		return { name, domain: domainFor(options.domain), appType };
	}

	return promptForNewApp(knownAppType);
}

function ensureEmptyTarget(targetDir: string): void {
	if (existsSync(targetDir) && readdirSync(targetDir).length > 0) {
		throw new CommandAbort({
			code: "TARGET_NOT_EMPTY",
			message: `Target directory is not empty: ${targetDir}. Pass --dir <empty-dir>. To work on an existing app's code, use \`whop apps pull\`.`,
		});
	}
}

async function fetchTemplateSource(
	templateId: string,
): Promise<{ template: WhopApp; sourceUrl: string }> {
	let template: WhopApp;
	try {
		template = await getApp(templateId);
	} catch (err) {
		throw new CommandAbort({
			code: "TEMPLATE_NOT_FOUND",
			message: `Could not load template app ${templateId}: ${err instanceof Error ? err.message : "unknown error"}`,
			retryable: true,
		});
	}
	const sourceUrl = template.production_web_build?.source_url;
	if (!sourceUrl) {
		throw new CommandAbort({
			code: "TEMPLATE_HAS_NO_SOURCE",
			message: `${template.name} (${template.id}) has no published source archive, so it can't be used as a template.`,
		});
	}
	return { template, sourceUrl };
}

/**
 * The full init flow: register the app on Whop, or take the never-deployed app
 * --app names, materialize the project —
 * the latest TanStack Start template, or a template app's published source —
 * wire it for Whop hosting, install dependencies, and git-init with an
 * initial commit. Shared with `deploy`'s interactive fallback for
 * not-yet-a-project directories.
 */
export async function runInitFlow(
	c: CommandContext,
	options: InitOptions,
	pm: PackageManager = ensurePackageManager(),
): Promise<InitResult> {
	const templateSource = options.template
		? await fetchTemplateSource(options.template)
		: null;

	const project = options.app
		? await existingProjectApp(options.app)
		: await newProjectApp(c, options, templateSource?.template);
	const targetDir = resolve(options.dir ?? `./${project.slug}`);
	ensureEmptyTarget(targetDir);

	const app = await project.claim();
	const retry = `whop apps init --app ${app.id}${options.template ? ` --template ${options.template}` : ""} --dir ${targetDir}`;

	// The target was empty, so everything in it is ours: a failed run removes
	// it, and the retry it prints starts from an empty directory again.
	let manualSteps: string[];
	try {
		manualSteps = await materializeProject({
			c,
			app,
			pm,
			retry,
			slug: project.slug,
			targetDir,
			templateSource,
		});
	} catch (err) {
		emptyDirectory(targetDir);
		throw err;
	}

	initGitRepo(c, targetDir);

	return { projectDir: targetDir, app, manualSteps };
}

async function materializeProject(input: {
	c: CommandContext;
	app: WhopApp;
	pm: PackageManager;
	retry: string;
	slug: string;
	targetDir: string;
	templateSource: { template: WhopApp; sourceUrl: string } | null;
}): Promise<string[]> {
	const { c, app, retry, targetDir, templateSource } = input;
	const spin = c.agent ? null : spinner();
	if (templateSource) {
		spin?.start(
			`Cloning ${templateSource.template.name} (${templateSource.template.id}) source archive`,
		);
		try {
			const zip = await downloadArchive(templateSource.sourceUrl);
			const fileCount = extractSourceArchive(zip, targetDir);
			spin?.stop(
				`Cloned ${fileCount} files from ${templateSource.template.name} → ${targetDir}`,
			);
		} catch (err) {
			spin?.error("Template clone failed");
			throw new CommandAbort({
				code: "TEMPLATE_CLONE_FAILED",
				message: `${err instanceof Error ? err.message : "Failed to clone the template source"}\n\nThe app ${app.id} is already registered — re-run \`${retry}\`.`,
				retryable: true,
			});
		}
	} else {
		spin?.start("Scaffolding the latest TanStack Start template");
		try {
			runTanstackCreate({ targetDir, projectName: input.slug, pm: input.pm });
			replaceStarterHome(targetDir, app.name);
			spin?.stop(
				`Scaffolded ${input.slug} from the latest TanStack Start template`,
			);
		} catch (err) {
			spin?.error("Scaffold failed");
			throw new CommandAbort({
				code: "SCAFFOLD_FAILED",
				message: `${err instanceof Error ? err.message : "Failed to scaffold the project"}\n\nThe app ${app.id} is already registered — fix the problem, then re-run \`${retry}\`.`,
			});
		}
	}

	// The template's own link config rides along in its source archive —
	// overwrite it so this project deploys to the new app, not the template.
	writeAppConfig(targetDir, linkConfigFor(app));

	const { manualSteps } = whopifyProject({
		targetDir,
		workerName: input.slug,
	});

	try {
		runInstall(c, targetDir);
	} catch (err) {
		throw new CommandAbort({
			code: "INSTALL_FAILED",
			message: `${err instanceof Error ? err.message : "Install failed"}\n\nThe app ${app.id} is already registered — re-run \`${retry}\`.`,
			retryable: true,
		});
	}

	return manualSteps;
}

function emptyDirectory(dir: string): void {
	if (!existsSync(dir)) return;
	for (const entry of readdirSync(dir)) {
		rmSync(join(dir, entry), { recursive: true, force: true });
	}
}

/**
 * A new app is registered only once the target directory is known to be free.
 * Its domain is claimed first, so a taken address fails before an app exists.
 */
async function newProjectApp(
	c: CommandContext,
	options: InitOptions,
	template: WhopApp | undefined,
): Promise<ProjectApp> {
	// A clone is the same kind of app as the source it was copied from, so
	// there is nothing to ask. Only `website` is inherited, because a website
	// can never be retyped — any other source still asks, or takes the default.
	const templateAppType =
		template?.app_type === "website" ? "website" : undefined;
	const { name, domain, appType } = await resolveNameAndDomain(
		c,
		options,
		templateAppType,
	);
	return {
		slug: slugify(name) || slugify(domain),
		claim: () =>
			registerApp({
				name,
				appType,
				domain,
				companyId: options.company_id,
				importedFromUrl: options.imported_from_url,
			}),
	};
}

/** Claims the domain, then registers the app on it, so a taken address fails before an app exists. */
export async function registerApp(input: {
	name: string;
	appType: NewAppType;
	domain: string;
	companyId?: string;
	importedFromUrl?: string;
}): Promise<WhopApp> {
	let domain: WhopDomain;
	try {
		domain = await ensureDomain({
			hostname: input.domain,
			accountId: input.companyId,
		});
	} catch (err) {
		if (err instanceof CommandAbort) throw err;
		throw new CommandAbort({
			code: "DOMAIN_UNAVAILABLE",
			message: `Couldn't claim ${input.domain}: ${err instanceof Error ? err.message : "unknown error"}\n\nNothing was created. Ask the user for another domain, then re-run with --domain.`,
			retryable: true,
		});
	}
	const domainId = domain.id;
	try {
		return await createApp({
			name: input.name,
			app_type: input.appType,
			domain_id: domainId,
			company_id: input.companyId,
			imported_from_url: input.importedFromUrl,
		});
	} catch (err) {
		throw new CommandAbort({
			code: "CREATE_FAILED",
			message:
				err instanceof Error ? err.message : "Failed to register the app",
			retryable: true,
		});
	}
}

/**
 * An app that has never been built — such as a website created on whop.com —
 * has nothing to pull, so its first code starts here. One with any build, live
 * or preview, is pulled instead: a fresh scaffold deployed over it would
 * replace that code.
 */
async function existingProjectApp(appId: string): Promise<ProjectApp> {
	let app: WhopApp;
	try {
		app = await getApp(appId);
	} catch (err) {
		throw new CommandAbort({
			code: "APP_NOT_FOUND",
			message: `Could not load app ${appId}: ${err instanceof Error ? err.message : "unknown error"}`,
			retryable: true,
		});
	}
	if (await hasWebBuilds(app.id)) {
		throw new CommandAbort({
			code: "APP_ALREADY_DEPLOYED",
			message: `${app.name} (${app.id}) already has builds, so starting fresh code for it would replace that code on the next deploy. Get its code with:\n  whop apps pull --app ${app.id}\nAdd --build abld_xxx for a preview build when nothing is live yet.`,
			cta: {
				commands: [
					{
						command: `apps pull --app ${app.id}`,
						description: "Fetch the deployed source",
					},
				],
			},
		});
	}
	return { slug: appSlug(app), claim: async () => app };
}

/**
 * Scaffolds get a git repo with an initial commit, like every modern create-*
 * tool — it is also what lets `whop apps pull` merge later. Skipped inside an
 * existing repo (the project is already under version control) and when git
 * isn't installed; only `pull` hard-requires git.
 */
function initGitRepo(c: CommandContext, targetDir: string): void {
	if (!gitInstalled()) {
		log(c, chalk.yellow("git is not installed — skipping repository setup."));
		return;
	}
	if (repoToplevel(targetDir)) return;
	try {
		gitInit(targetDir);
		commitAll(targetDir, "Initial commit from whop apps init");
	} catch (err) {
		log(
			c,
			chalk.yellow(
				`Couldn't create the git repository (${err instanceof Error ? err.message : "unknown error"}) — continuing without one.`,
			),
		);
	}
}
