import { resolveActiveAccountId } from "../api/index.js";
import { makeWhopRequest } from "../journey/client.js";
import { PLATFORM_DOMAIN_SUFFIX } from "./config.js";
import { CommandAbort } from "./shared.js";

export type WhopApp = {
	id: string;
	name: string;
	app_type?: string | null;
	hosted_url?: string | null;
	base_url?: string | null;
	domains?: Array<{ id: string; domain: string; status: string }> | null;
	account?: { id?: string } | null;
	secrets?: Record<string, string> | null;
	production_web_build?: { id?: string; source_url?: string | null } | null;
	created_at?: number;
};

export type WhopAppBuild = {
	id: string;
	status: "draft" | "pending" | "approved" | "rejected";
	platform: string;
	checksum: string;
	is_production: boolean;
	source_url?: string | null;
	created_at?: number;
};

type WhopFile = {
	id: string;
	upload_status: string;
	upload_url?: string | null;
	upload_headers?: Record<string, string> | null;
};

export async function createApp(input: {
	name: string;
	app_type?: string;
	domain_id?: string;
	company_id?: string;
	imported_from_url?: string;
}): Promise<WhopApp> {
	const company_id = input.company_id ?? (await resolveActiveAccountId());
	return makeWhopRequest<WhopApp>("POST", "/apps", { ...input, company_id });
}

const DEV_TOKEN_TTL_MS = (3 * 60 - 1) * 60 * 1000;

/**
 * Mints a short-lived access token from the CLI's credential (POST
 * /access_tokens): with an API key it's a company token inheriting the key's
 * permissions; with OAuth login the user and scopes come from the token
 * itself (which also pins the expiry). `whop apps dev` injects it into the
 * dev server so server-side SDK calls work without manual env vars.
 */
export async function createDevAccessToken(): Promise<{
	token: string;
	expires_at?: string | number | null;
}> {
	const company_id = await resolveActiveAccountId();
	return makeWhopRequest("POST", "/access_tokens", {
		...(company_id ? { company_id } : {}),
		expires_at: new Date(Date.now() + DEV_TOKEN_TTL_MS).toISOString(),
	});
}

export async function listApps(): Promise<WhopApp[]> {
	const companyId = await resolveActiveAccountId();
	const query = companyId ? `?company_id=${encodeURIComponent(companyId)}` : "";
	const response = await makeWhopRequest<{ data?: WhopApp[] }>(
		"GET",
		`/apps${query}`,
	);
	return response.data ?? [];
}

export async function getApp(appId: string): Promise<WhopApp> {
	return makeWhopRequest<WhopApp>("GET", `/apps/${appId}`);
}

export type WhopDomain = {
	id: string;
	domain: string;
	status: string;
	website?: { app?: { id: string } | null } | null;
	registration?: { purchase_url?: string | null } | null;
	availability?: { available?: boolean } | null;
	issues?: Array<{ message: string }> | null;
};

/**
 * What the owner still has to do before each of the app's domains serves it:
 * pay, or publish DNS records. These steps follow a finished init or deploy, so
 * a domain whose status can't be read becomes a step to check it by hand
 * rather than a failure of the ship.
 */
export async function pendingDomainSteps(app: WhopApp): Promise<string[]> {
	const pending = (app.domains ?? []).filter((d) => d.status !== "ready");
	const steps = await Promise.all(
		pending.map(async ({ id, domain }) => {
			let details: WhopDomain;
			try {
				details = await makeWhopRequest<WhopDomain>("GET", `/domains/${id}`);
			} catch (err) {
				return [
					`Couldn't read ${domain}'s status (${err instanceof Error ? err.message : "unknown error"}); check it with \`whop domains get ${domain}\`.`,
				];
			}
			const purchaseUrl = details.registration?.purchase_url;
			if (purchaseUrl)
				return [`Pay for ${domain} to finish buying it: ${purchaseUrl}`];
			const issues = details.issues ?? [];
			if (issues.length === 0) {
				return [
					`${domain} is ${details.status} and not serving yet; check it with \`whop domains get ${domain}\`.`,
				];
			}
			return issues.map(
				(issue) =>
					`${domain}: ${issue.message} (records: \`whop domains get ${domain}\`)`,
			);
		}),
	);
	return steps.flat();
}

/**
 * How a new domain joins the account: a whop.site name is claimed as an
 * address; a domain that can be registered is bought, which charges nothing
 * until the owner pays at its `purchase_url`; any other domain is connected by
 * proving DNS control with the TXT record in `issues`.
 */
async function ownerFor(
	hostname: string,
): Promise<{ platform: {} } | { registration: {} } | { verification: {} }> {
	if (hostname.endsWith(`.${PLATFORM_DOMAIN_SUFFIX}`)) return { platform: {} };
	const lookup = await makeWhopRequest<WhopDomain>(
		"GET",
		`/domains/${encodeURIComponent(hostname)}`,
	);
	return lookup.availability?.available
		? { registration: {} }
		: { verification: {} };
}

/**
 * Puts `hostname` on the account — the account's own domain when it has one,
 * otherwise a new one joined as `ownerFor` decides — and serves `appId` on it
 * when one is given.
 */
export async function ensureDomain(input: {
	hostname: string;
	accountId?: string;
	appId?: string;
}): Promise<WhopDomain> {
	const website = input.appId ? { website: { app_id: input.appId } } : {};
	const accountId = input.accountId ?? (await resolveActiveAccountId());
	const query = new URLSearchParams({
		domain: input.hostname,
		...(accountId ? { account_id: accountId } : {}),
	});
	const owned = await makeWhopRequest<{ data?: WhopDomain[] }>(
		"GET",
		`/domains?${query}`,
	);
	const existing = owned.data?.[0];
	const serving = existing?.website?.app?.id;
	if (serving && serving !== input.appId) {
		throw new CommandAbort({
			code: "DOMAIN_IN_USE",
			message: `${input.hostname} already serves ${serving}, so it was left as it is. To work on that app, run \`whop apps pull --app ${serving}\`, or \`whop apps init --app ${serving}\` if it has never been deployed. Otherwise ask the user for another domain.`,
		});
	}
	if (existing) {
		return input.appId
			? makeWhopRequest<WhopDomain>("PATCH", `/domains/${existing.id}`, website)
			: existing;
	}
	return makeWhopRequest<WhopDomain>("POST", "/domains", {
		account_id: accountId,
		domain: input.hostname,
		...(await ownerFor(input.hostname)),
		...website,
	});
}

export async function updateAppSecrets(
	appId: string,
	secrets: Record<string, string | null>,
): Promise<WhopApp> {
	return makeWhopRequest<WhopApp>("PATCH", `/apps/${appId}`, { secrets });
}

export async function createAppBuild(input: {
	app_id: string;
	checksum: string;
	file_id: string;
	source_file_id?: string;
}): Promise<WhopAppBuild> {
	return makeWhopRequest<WhopAppBuild>("POST", "/app_builds", {
		app_id: input.app_id,
		platform: "web",
		checksum: input.checksum,
		attachment: { id: input.file_id },
		...(input.source_file_id
			? { source_attachment: { id: input.source_file_id } }
			: {}),
	});
}

/** Whether the app has any web build at all — live or preview — and so has had code before. */
export async function hasWebBuilds(appId: string): Promise<boolean> {
	const query = new URLSearchParams({
		app_id: appId,
		platform: "web",
		first: "1",
	});
	const builds = await makeWhopRequest<{ data?: WhopAppBuild[] }>(
		"GET",
		`/app_builds?${query}`,
	);
	return (builds.data?.length ?? 0) > 0;
}

export async function getAppBuild(buildId: string): Promise<WhopAppBuild> {
	return makeWhopRequest<WhopAppBuild>("GET", `/app_builds/${buildId}`);
}

export async function promoteAppBuild(buildId: string): Promise<WhopAppBuild> {
	return makeWhopRequest<WhopAppBuild>(
		"POST",
		`/app_builds/${buildId}/promote`,
		{},
	);
}

/**
 * Uploads a build or source archive: creates a file record, PUTs the bytes to
 * the presigned URL, and returns the file id. The archive is public so the
 * hosting worker can fetch it from a stable CDN URL. The file is still
 * `pending` when this returns — call waitForFileReady before attaching it to
 * a build.
 */
export async function uploadBuildArchive(
	zip: Uint8Array,
	filename: string,
): Promise<string> {
	const file = await makeWhopRequest<WhopFile>("POST", "/files", {
		filename,
		visibility: "public",
	});

	if (!file.upload_url) {
		throw new Error("File creation did not return an upload URL.");
	}

	const body = new Uint8Array(zip).buffer as ArrayBuffer;
	const uploadResponse = await fetch(file.upload_url, {
		method: "PUT",
		headers: file.upload_headers ?? { "Content-Type": "application/zip" },
		body,
	});
	if (!uploadResponse.ok) {
		throw new Error(
			`Archive upload failed: ${uploadResponse.status} ${await uploadResponse.text()}`,
		);
	}

	return file.id;
}

/**
 * Polls the file until upload processing marks it `ready`. Direct-to-S3 uploads
 * complete asynchronously (the S3 event pipeline verifies the object and flips
 * the status), so a build can only attach the file once it is ready.
 */
export async function waitForFileReady(
	fileId: string,
	timeoutMs = 60_000,
): Promise<void> {
	const deadline = Date.now() + timeoutMs;
	while (Date.now() < deadline) {
		const file = await makeWhopRequest<WhopFile>("GET", `/files/${fileId}`);
		if (file.upload_status === "ready") return;
		await sleep(1_000);
	}
	throw new Error(
		"Timed out waiting for the build archive to finish processing.",
	);
}

export async function waitForBuildPromotion(
	buildId: string,
	timeoutMs = 30_000,
): Promise<WhopAppBuild> {
	const deadline = Date.now() + timeoutMs;
	let latest = await getAppBuild(buildId);
	while (Date.now() < deadline) {
		if (latest.is_production) return latest;
		if (latest.status === "rejected") {
			throw new Error("Build was rejected and cannot be promoted.");
		}
		await sleep(750);
		latest = await getAppBuild(buildId);
	}
	return latest;
}

function sleep(ms: number): Promise<void> {
	return new Promise((resolve) => setTimeout(resolve, ms));
}
